/**
 * Keep track of the time in the simulation
 * and specify if it is day or night
 *
 * @version 2022.02.24
 */
public class Time
{
    // true if it is night
    private boolean isNight;
    // keep track of the simulation steps.
    private SimulationStep simStep;
    // keep track of the hour of the day
    private int currentHour;
    // the number of steps before the type of day changes
    private static final int DAY_CHANGE = 1;

    /**
     * Construct a Time object with the given parameters.
     *
     * @param simStep (SimulationStep) The object of SimulationStep to use for keeping track of the steps.
     * @param startNight (boolean) true if first iteration is night, false if day.
     */
    public Time(SimulationStep simStep, boolean startNight)
    {
        this.simStep = simStep;
        isNight = startNight;

        if(isNight) {
            currentHour = 18;
        }
        else {
            currentHour = 6;
        }
    }

    /**
     * @return (boolean) true if night, false otherwise.
     */
    public boolean getIsNight()
    {
        return isNight;
    }

    /**
     * Create a String indicating night or day and the specific hour.
     *
     * @return (String) A String with the time's full information.
     */
    public String timeString()
    {
        String tString = "";

        if(isNight) {
            tString += "Night \t";
        }
        else {
            tString += "Day \t";
        }

        tString += "(" + getHourDisplay() + ")";

        return tString;
    }

    /**
     * Change the day status if 'CHANGE_STEPS' steps have passed, and increment the hours.
     */
    public void timeStep()
    {
        int step = simStep.getCurrentStep();

        if(step != 0 && (step+1) % DAY_CHANGE == 0) { // step+1 because step starts with 0
            toggleIsNight();
        }

        incHour();
    }

    /**
     * Change the current status of the time.
     */
    private void toggleIsNight()
    {
        isNight = ! isNight;
    }

    /**
     * Increment the hours to go through the day evenly.
     */
    private void incHour()
    {
        currentHour = (currentHour + (24 / (DAY_CHANGE * 2))) % 24;
    }

    /**
     * Create a string displaying time in 24-hour style.
     *
     * @return (String)a String holding the current time.
     */
    private String getHourDisplay()
    {
        if(currentHour < 10)
        {
            return "0" + currentHour + ":00";
        }

        return currentHour + ":00";
    }
}

/**
 * An enum that specifies the values and actions of the different
 * climate change scenarios to approximate the real scenarios projected by the IPCC.
 *
 * @version 2022.02.28
 */
public enum ClimateScenarios
{
    SCENARIO1(0,0), SCENARIO2(1, 0.05), SCENARIO3(2, 0.15), SCENARIO4(3, 0.3);

    private double concreteChange;
    private final double changePercentage;

    /**
     * Create an appropriate Climate Scenario
     *
     * @param concreteChange (int) hold the actual temperature change value
     * @param changePercentage (double) the change percentage that is added to the concreteChange each year
     */
    ClimateScenarios(int concreteChange, double changePercentage)
    {
        this.concreteChange = concreteChange;
        this.changePercentage = changePercentage;
    }

    /**
     * @return (int) the concreteChange as a rounded int
     */
    public int getClimateChangeEffect()
    {
        return (int) Math.round(concreteChange);
    }

    /**
     * Increases the concreteChange by the changePercentage.
     */
    public void doClimateChange()
    {
        concreteChange = concreteChange + (changePercentage * concreteChange);
    }
}

/**
 * A generic class that represents a season
 * of the year
 *
 * @version 2022.02.16
 */
public class  Season
{
    private final String name;
    private int aveTemperature;
    private final int tempChange;
    // store the current temperature of this season
    private Thermometer currentTemp;

    /**
     * Initialise the Season object
     *
     * @param name (String) the name of the season
     * @param aveTemperature (int) the average temperature of this season
     * @param tempChange (int) the amount that the season's temperature can go up or down from the average temperature
     */
    public Season(String name, int aveTemperature, int tempChange)
    {
        this.name = name;
        this.aveTemperature = aveTemperature;
        this.tempChange = tempChange;

        currentTemp = new Thermometer(aveTemperature);
    }

    /**
     * @return (String) the name of the season
     */
    public String getName()
    {
        return name;
    }

    /**
     * @return (int) average Temperature
     */
    public int getAveTemperature()
    {
        return aveTemperature;
    }

    /**
     * Increment the season's average temperature by the given parameter
     *
     * @param inc (int) the increment
     */
    public void incAveTemperature(int inc)
    {
        aveTemperature += inc;
    }

    /**
     * @return (int) The temperature change.
     */
    public int getTempChange()
    {
        return tempChange;
    }

    /**
     * @return (int) The upper limit temperature that the season could reach
     */
    public int getUpperLimitTemp()
    {
        return aveTemperature + tempChange;
    }

    /**
     * @return (int) The lower limit temperature that the season could drop to
     */
    public int getLowerLimitTemp()
    {
        return aveTemperature - tempChange;
    }

    /**
     * @return (Thermometer) A reference to the Thermometer object of this season
     */
    public Thermometer getCurrentTemp()
    {
        return currentTemp;
    }

}

